// server.js

const express = require('express');
const app = express();
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

app.use(cors());
app.use(express.json());

let todos = [];

app.get('/todos', (req, res) => {
  try {
    const completedFilter = req.query.completed;
    let filteredTodos = todos;

    if (completedFilter === 'true') {
      filteredTodos = todos.filter(todo => todo.completed);
    } else if (completedFilter === 'false') {
      filteredTodos = todos.filter(todo => !todo.completed);
    }

    res.json(filteredTodos);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/todos/:id', (req, res) => {
  try {
    const todo = todos.find(todo => todo.id === req.params.id);

    if (!todo) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    res.json(todo);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.post('/todos', (req, res) => {
  try {
    const { title } = req.body;

    if (!title || typeof title !== 'string' || title.length < 1 || title.length > 100) {
      return res.status(400).json({ error: 'Invalid title. Must be a string between 1 and 100 characters.' });
    }

    const newTodo = {
      id: uuidv4(),
      title,
      completed: false,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    todos.push(newTodo);
    res.status(201).json(newTodo);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.put('/todos/:id', (req, res) => {
  try {
    const { title, completed } = req.body;
    const todoIndex = todos.findIndex(todo => todo.id === req.params.id);

    if (todoIndex === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    const updatedTodo = {
      ...todos[todoIndex],
      title: title || todos[todoIndex].title,
      completed: typeof completed === 'boolean' ? completed : todos[todoIndex].completed,
      updatedAt: new Date()
    };

    todos[todoIndex] = updatedTodo;
    res.json(updatedTodo);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.delete('/todos/:id', (req, res) => {
  try {
    const todoIndex = todos.findIndex(todo => todo.id === req.params.id);

    if (todoIndex === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    const deletedTodo = todos[todoIndex];
    todos.splice(todoIndex, 1);
    res.json(deletedTodo);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = app;
