// test-server.js

const request = require('supertest');
const app = require('./server');

describe('Todo API', () => {
  let todo;

  it('should create a new todo', async () => {
    const res = await request(app)
      .post('/todos')
      .send({ title: 'Test Todo' });

    expect(res.status).toBe(201);
    expect(res.body).toHaveProperty('id');
    expect(res.body.title).toBe('Test Todo');
    expect(res.body.completed).toBe(false);

    todo = res.body;
  });

  it('should list all todos', async () => {
    const res = await request(app).get('/todos');

    expect(res.status).toBe(200);
    expect(Array.isArray(res.body)).toBe(true);
    expect(res.body.some(t => t.id === todo.id)).toBe(true);
  });

  it('should get a single todo by id', async () => {
    const res = await request(app).get(`/todos/${todo.id}`);

    expect(res.status).toBe(200);
    expect(res.body.id).toBe(todo.id);
    expect(res.body.title).toBe('Test Todo');
  });

  it('should update a todo', async () => {
    const res = await request(app)
      .put(`/todos/${todo.id}`)
      .send({ title: 'Updated Todo', completed: true });

    expect(res.status).toBe(200);
    expect(res.body.title).toBe('Updated Todo');
    expect(res.body.completed).toBe(true);

    todo = res.body;
  });

  it('should delete a todo', async () => {
    const res = await request(app).delete(`/todos/${todo.id}`);

    expect(res.status).toBe(200);
    expect(res.body.id).toBe(todo.id);

    const getRes = await request(app).get('/todos');
    expect(getRes.body.some(t => t.id === todo.id)).toBe(false);
  });

  it('should return 404 for non-existent todo', async () => {
    const res = await request(app).get(`/todos/${uuidv4()}`);

    expect(res.status).toBe(404);
    expect(res.body.error).toBe('Todo not found');
  });

  it('should validate title on create', async () => {
    let res = await request(app)
      .post('/todos')
      .send({ title: '' });

    expect(res.status).toBe(400);
    expect(res.body.error).toBe('Invalid title. Must be a string between 1 and 100 characters.');

    res = await request(app)
      .post('/todos')
      .send({ title: 'a'.repeat(101) });

    expect(res.status).toBe(400);
    expect(res.body.error).toBe('Invalid title. Must be a string between 1 and 100 characters.');
  });
});
